import sys

def min_back_steps(f) -> int:
    steps = list(f)
    n = len(steps)
    back_steps = 0
    last_step = None
    for step in steps:
        if step == 'L':
            if last_step != 'R':
                back_steps += 1
        elif step == 'R':
            if last_step != 'L':
                back_steps += 1
        last_step = step
    return back_steps

def reconstruct_history(f):
    n = len(f)
    back_steps = min_back_steps(f)
    history = []

    # Fill the first step from the back.
    for i in range(n-1, 0, -1):
        if f[i] == 'L' and f[i-1] != 'L':
            history.append(i)
            f[i-1] = 'L'
        elif f[i] == 'L' and f[i-1] != 'R':
            history.append(i)
            f[i-1] = 'R'

    # Fill the others from the front, checking left foot usage.
    for i in range(1, n):
        if back_steps > 0 and f[i] == 'L' and f[i-1] != 'R':
            back_steps -= 1
        else:
            history.append(i)

    return f, history

def main():
    s = sys.stdin.readline().strip()
    f, history = reconstruct_history(s)
    back_steps = min_back_steps(f)
    print(back_steps)

if __name__ == "__main__":
    main()
