def subarrays_stack_exportable_count(n, a):
    stack, count, current_subarray = [], 0, []

    for i in range(n):
        if not stack or a[i] > stack[-1]: 
            stack.append(a[i])
            current_subarray.append(i + 1)
            continue

        while stack and a[i] < stack[-1]: 
            top_index = stack.pop()
            if not stack:
                count += len(current_subarray)
                current_subarray = []
            else:
                count += current_subarray.index(top_index) + 1
                current_subarray = stack
                current_subarray.append(i + 1)
                break

        if not stack:
            current_subarray = []

