def is_bitonic(arr):
    return arr[0] < arr[len(arr) // 2] and arr[len(arr) // 2] > arr[-1]

def find_bitonic_matrix(n, m):
    max_values = [0] * n * m

    # Fill the matrix with distinct numbers from 1 to n*m
    for i in range(n):
        for j in range(m):
            max_values[i * m + j] = i * m + j + 1

    # Try to construct a bitonic matrix for each possible matrix starting with (i, j)
    for i in range(n):
        for j in range(m):
            augment(i, j, n, m, max_values, i * m + j)
    res = construct(max_values, n, m)

    # Check if the resulting matrix is bitonic
    for y_row in res:
        max_y = max(y_row)
        for y_pos in range(len(y_row) // 2):
            if max_y < y_row[y_pos] or y_row[y_pos] < y_row[y_row.index(max_y, y_pos + 1) - 1]:
                return -1

    for i in range(n):
        max_x = res[i][0]
        for y_pos in range(len(res[i])):
            if res[i][y_pos] > max_x:
                return -1
    return res

def augment(i, j, n, m, max_values, i1):
    # Fixing values in matrix
    max_values[i1] = i1 * m + j + 1;
    for col in range(i1 + 1, n + m):
        if is_bitonic([max_values[y - j] + 1 for y in range(cols + 1, col)]):
            augment(i1, j, n, m, max_values, col)
            return

def construct(values, n, m):
    cols = max(m, n)
    res = []
    for r in range(n * m, 0, -1):
        col_values = []
        for col in range(cols):
            y = max(values[y - j] for y in range(r))
            for j in range(cols - 1, 0, -1):
                if y < values[y - j] or values[y - j] < values[y - j - 1]:
                    col_values.append(max_values[y - j])
                    break
        res.append(col_values)
    return res
