                counts['01'] += 1
            elif S[i-1] == '1' and S[i] == '0':
                counts['10'] += 1

    for i in range(N):
        if i > 0:
            if S[i-1] == '1':
                counts['1'] += 1
            if i < N-1:
                if S[i+1] == '1':
                    counts['1'] += 1
            counts['0'] += counts['1']

    # Count all substrings by joining prefixes (0's, 1's, 01's)
    count = 0
    for i in range(1, N+1):
        count += i * (i - 1) // 2
    for i in range(1, N+1):
        count += N * (i - 1)
    return count - counts['10'], counts['01'] + counts['01']

