def find_intersections(edges):
    x_coords = defaultdict(set)
    y_coords = defaultdict(set)
    for x1, y1, x2, y2 in edges:
        x_coords[x1].add((x1, y1))
        x_coords[x2].add((x2, y2))
        y_coords[y1].add((x1, y1))
        y_coords[y2].add((x2, y2))

    intersections = []
    for x, xs in x_coords.items():
        for y, ys in y_coords.items():
            if xs & ys:
                intersections.append((x, y))

    return intersections

def find_lost_segments(intersections, start_coordinates):
    lost_segments = []
    for x, y in intersections:
        if (x - start_coordinates[0]) ** 2 + (y - start_coordinates[1]) ** 2 == min((x - s[0]) ** 2 + (y - s[1]) ** 2 for s in lost_segments):
