from collections import Counter

def min_backwards_steps(steps):
    # Count the difference between repeated and unrepeated steps
    difference_count = sum(1 for step, count in Counter(steps).items() if count >= 2)
    return difference_count

def reconstruct_footprints(steps):
    left_footprints = []
    right_footprints = []

    for step in steps:
        if step == 'L':
            left_footprints.append((len(left_footprints) + 1) % 2)
        else:
            right_footprints.append(len(right_footprints) + 1)

    left_order = [left_footprints[0]]
    right_order = [right_footprints[0]]

    for i in range(1, len(left_footprints)):
        if left_footprints[i] == left_order[-1] and right_footprints[i] == right_order[-1]:
            left_footprints[i], left_order[-1] = left_footprints[i], left_order[-1]
            right_footprints[i], right_order[-1] = right_footprints[i], right_order[-1]
        if left_footprints[i] > right_footprints[i]:
            left_footprints[i], right_footprints[i] = left_footprints[i], right_footprints[i]
            left_order.append(left_footprints[i])
        else:
            right_order.append(right_footprints[i])

    all_steps = left_order + right_order if steps.count('L') > steps.count('R') else right_order + left_order

    return ' '.join(map(str, all_steps))

if __name__ == "__main__":
    s = "RRLRL"
    print(min_backwards_steps(s))  # Output: 1
    print(reconstruct_footprints(s))  # Output: 2 5 1 3 4
