    slope1 = point1[1] - point1[3] / (point1[0] - point1[2]) if point1[0] - point1[2] == 0 else point1[1] - point1[3]
    slope2 = point2[1] - point2[3] / (point2[0] - point2[2]) if point2[0] - point2[2] == 0 else point2[1] - point2[3]
    invSlope1 = s * -1 / d1 + d2 / s
    s, d1, d2 = slope1, 1, n
    conversion = conversion if areCollinear(points, [p1[0], p1[1], p1[2]]) and not areCollinear(points, [p1[2], p1[0], p1[2]]) else ((p2[0], p2[1], p2[2], p2[3]) if areCollinear(points, [p2[0], p2[1], p2[2]]) and not areCollinear(points, [p2[2], p2[0], p2[2]]) else ((point5[0], point5[1], point5[2], point5[3]) if areCollinear(points, [point5[0], point5[1], point5[2]]) and not areCollinear(points, [point2[2], point5[0], point5[2]]) else ((point5[0], point5[1], point5[2], point5[3]) if areCollinear(points, [point5[0], point5[1], point5[2]]) and not areCollinear(points, [point2[2], point5[0], point5[2]]) else conversion)))
