from collections import deque

def find_stacks(n_list):
    stack_count = 0
    last_index = -1
    output = []
    for i, x in enumerate(n_list):
        if i == 0:
            stack_count = next(n_list, None) == x and 0
            last_index = i
            continue
        if x == next(n_list, None) and i - last_index > 1:
            if next(n_list, None) == n_list[i - 1]:
                stack_count += 1
            else:
                stack_count -= 1
        output.append([last_index, i])
        last_index = i
    return output, stack_count

def stack_externeability(n_list):
    index = [i+1 for i in range(len(n_list))]
    output = []
    stack_stack = []
    for i, x in enumerate(n_list):
        stack_stack.append(x)
        for j, y in enumerate(stack_stack):
            if j - index[y-1] < x - 1:
                stack_stack = stack_stack[j:y-1][::-1] + stack_stack[y:]
                index[y-1] = j
                break 
            else:
                if index[y-1] + x == index[i]:
                    index[i] = j
                    break
        if not stack_stack:
            stack_stack = []
        else:
            stack_stack += next(n_list, None)
            index[i] = stack_stack.index(next(n_list, None))
        output.append(len(stack_stack))
    return output

