def solve(N, M, K):
    mod = 10**9 + 7
    dp = [[0] * 3 for _ in range(N + M + K + 1)]

    # Initialize base cases for dp
    for i in range(M + 1):
        if i == 1 or i == 2:
            dp[1][i] = dp[2][i] = 1
            dp[1][0] = dp[2][0] = 2
        for j in range(K + 1):
            dp[1][j] = (dp[1][j] + dp[0][j] * dp[1][i]) % mod
    for i in range(2, min(M + 1, N + 2 * K) + 1):
        for j in range(M + 1):
            for k in range(K + 1):
                dp[i][j] = (dp[i][j] + dp[i-1][j-1] * min(k, j) * min(k, j)) % mod

    return dp[-1][N].mod(mod)

