import sys

def check(edges, colors):
    tree = {i:[] for i in range(len(edges)+1)}
    for i in edges:
        tree[i[0]].append(i[1])
        tree[i[1]].append(i[0])

    visit_map = {}

    def dfs(u):
        cycle = []
        for v in tree[u]:
            if v in visit_map and visit_map[v] is True:
                cycle.append(v)
            elif v in visit_map and visit_map[v] is False:
                cycle = []
                break
            elif visit_map.get(v) is not None:
                continue
            elif v not in tree or tree[v] == []:
                continue
            depth = 1
            while v in tree:
                v = -1 # mark as visited and parellel
                for i in tree[v]:
                    if i != u:
                        depth += 1
                        dfs(i)
                if v in cycle:
                    break
                visit_map[v] = False
                if v in cycle:
                    break
            cycle.pop()
            cycle.append(v)

        if len(cycle) > 0:
            for i in cycle:
                colors[i] = 'B'
            visit_map = {}
            continue

        for v in tree[u]:
            if v not in colors:
                colors[v] = 'W'
                for i in tree[v]:
                    if i != u:
                        dfs(i)
            visit_map[v] = True

    treesize = len(edges) + 1
    for vertex in range(treesize):
        dproblem = {}
        dproblem[vertex] = 'W'
        dfs(vertex)

    return dproblem    


