from collections import deque

def shortest_path(a, N):
    if a[0] == 1:
        return 1
    elif N == 1:
        return max(a)
    visited = [False] * N
    queue = deque([(1, -1, 0)])  # (current_index, previous_index, cumulative_cost)
    max_gap = -1

    while queue:
        idx, prev, cost = queue.popleft()

        for next_idx in range(idx, min(idx + (a[idx]), N)):
            if not visited[next_idx]:
                queue.append((next_idx, idx, cost | a[next_idx]))
                visited[next_idx] = True

            if next_idx > idx + a[idx] or next_idx > N:
                max_gap = max(max_gap, idx - prev + 1)

    for i in range(1, N):
        min_cost = sum(a[:i+1]) & ((1<<i)-1)  # Calculate the bitwise OR
        gap = i if min_cost == reduce(lambda x, y: x | y, a[:i+1]) else max_gap
        if not visited[i]:
            queue.append((i, -1, min_cost))
            visited[i] = True

    if queue:
        min_cost = reduce(lambda x, y: x | y, a[])
        return -1 if max_gap != N-1 else min_cost - 1

    return 0

