def is_stack_exterminable(stacks: List[List[int]]) -> bool:
    queue: List[int] = collections.deque()
    for s in stacks:
        for i in range(len(s)):
            if not queue:
                queue.append(s[-1])
            else:
                if s[-1] < queue[0] or s[i] < queue[0]:
                    queue.append(s[i])
                queue.popleft()

    return not queue

def count_stack_exterminable_subarrays(nums: List[int]) -> int:
