from collections import defaultdict, deque
from typing import List

def buildTree(families: List[Tuple[int, int]]) -> List[List[int]]:
    tree: List[List[int]] = [[] for _ in range(len(families) + 1)]
    for u, v in families:
        tree[u].append(v)
        tree[v].append(u)
    return tree

def bfs(tree: List[List[int]], start: int) -> List[int]:
    visited = [False] * (len(tree) + 1)
    distances = [float('inf')] * (len(tree) + 1)
    distances[start] = 0
    queue = deque([start])

    while queue:
        current = queue.popleft()
        for neighbor in tree[current]:
            if not visited[neighbor]:
                visited[neighbor] = True
                distances[neighbor] = distances[current] + 1
                queue.append(neighbor)

    return distances

def minimumTrees(n: int, tree: List[List[int]], friendships: List[Tuple[int, int]]) -> int:
    distance = defaultdict(lambda: float('inf'))
    iterator = iter(range(1, n + 1))
    for u, v in friendships:
        u, v = min(u, v), max(u, v)
        distance[u, v] = distance[v, u] = 1 if u == v else 0

    for u, v in friendships:
        if distance[u, v] or distance[v, u]:
            distance[u, v] = 0

    nonFriends = set(tree[0])
    families = defaultdict(set)

    for u, v in friendships:
        families[u].add(v)
        families[v].add(u)
        nonFriends.remove(v)
        nonFriends.remove(u)

    for start in iterator:
        queue = deque([start])
        stop = distance[start] + 1
        result = start
        while queue:
            current = queue.popleft()
            for neighbor in nonFriends:
                if distance[current, neighbor] > stop:
                    queue.append(neighbor)
                    distance[current, neighbor] = start
                    distance[neighbor, current] = start
            result = current
        for start in iterator:
            if distance[0, start] > stop:
                distance[0, start] = start
                distance[start, 0] = start
        for neighbor in families[result]:
            distance[result, neighbor] = distance[neighbor, result] = 1 if neighbor == start else 0
    return result

