from typing import List

def build_bitonic_matrix(n, m, matrix) -> List[List[int]]:
    rows = [[matrix[0][0], matrix[0][1], matrix[1][2]]]
    columns = [[matrix[n-1][n-1], matrix[n-1][2*n-3], matrix[2*n-3][n-1]]]

    for i in range(1, n):
        for j in range(m):
            if j % 2:
                heapq.heappush(rows, [matrix[i][j], matrix[i+1][j-1], matrix[i+2*n-2][j-2]])
            else:
                heapq.heappush(columns, [matrix[i][j], matrix[i+1][j+1], matrix[i+2*n-2][j+2]])

    bitonic_matrix = []
    for r in rows:
        bitonic_matrix.append(r)
        bitonic_matrix.append(0)
        bitonic_matrix.append(r[1])
    for c in columns:
        bitonic_matrix.append(c)
        bitonic_matrix.append(0)
        bitonic_matrix.append(c[1])

    for _ in range(2 * n * m - 4 * n):
        heapq.heappop(bitonic_matrix)
        heapq.heappop(bitonic_matrix)

    return bitonic_matrix[:-1]

def is_bitonic(row: List[int]) -> bool:
    return row[1] > row[0] and row[-2] > row[-3] and all(a > b for a, b in zip(row, reversed(row)))

def is_bitonic_matrix(matrix: List[List[int]]) -> bool:
    n, m = len(matrix), len(matrix[0])
    for i in range(n):
        if not is_bitonic([matrix[i][j] for j in range(m)]):
            return False
    for j in range(m):
        if not is_bitonic([matrix[i][j] for i in range(n)]):
            return False
    return True

def solve(r: int, c: int) -> List[List[int]]:
    for _ in range(r - 1):
        r -= 1
        for _ in range(c - 1):
            c -= 1
        matrix = [[j + 1] + ([i // r][i % r] for i in range(1, r + c)) + ([k // c][k % c] for k in range(r, 1, -1)) for j in range(c)]
        if is_bitonic_matrix(matrix):
            return matrix
    return build_bitonic_matrix(r, c, matrix)

