MOD = 998244353

def cmppower(a, x, p):
    res = 1
    mul = a % p
    while x:
        if x & 1:
            res = (res * mul) % p
        mul = (mul * mul) % p
        x >>= 1
    return res

def handle_m(x):
    res = cmppower(31, x, MOD)
    return res

def query(n, m):
    cnt = [0] * (n + m + 1)
    ans = 0
    for i in range(1, n + 1):
        cnt[i] = cnt[i - 1] + i + i % 2
    for i in range(0, cnt[1]):
        ans = (ans + handle_m(cnt[1] - i)) % MOD
    for k in range(2, n + m + 1):
        k1 = k // 2
        ans = (ans + (cmppower(31, k) * cnt[k]) % MOD) % MOD
        if (k & 1) == False:
            ans = (ans - (cmppower(31, k1) * cnt[k1]) % MOD + MOD) % MOD
    res = sum((cnt[i] * (i % 2) * cmppower(31, m - i)) % MOD for i in range(m + 1)) % MOD
    return ans, mod_subres(dtype_int64_t, res)

def mod_subres(dtype_int64_t dst, src) -> dtype_int64_t:
    while src != 0:
        t = src % 998244353
        src = src // 998244353
        dst += t
        dst %= 998244353
    return dst
