def dp_memoization(A, n, memo):
    if n == 1:
        return 0
    if memo[n] > 0:
        return memo[n]

    min_cost = float('inf')
    for i in range(1, n+1):
        cost = A[i-1]
        for j in range(1, min(i+A[i-1], n)+1):
            _, x = dp_memoization(A, j, memo)
            cost |= x
        min_cost = min(min_cost, cost)

    memo[n] = min_cost
    return memo[n]

