from collections import defaultdict

def min_seconds_to_blackify(tree_count, edges, initial_colors):
    # Build the graph
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Set to track which vertices are in state 0 (white) and which are in state 1 (black)
    state_tracker = {0: [], 1: []}

    # Check if the initial state blocks the cat from achieving the goal
    if initial_colors[0] == 'W':
        return tree_count

    time_to_blackify = float('inf')

    # Function to propagate state changes
    def propagate():
        memo = [0] * tree_count
        for u in range(1, tree_count):
            found, time_diff = False, float('inf')
            for v in graph[u]:
                if state_tracker[v % 2] > 0:
                    if memo[v] == 0:
                        memo[v] = 1
                        found = True
                    else:
                        time_diff = min(time_diff, memo[v] + 1 - 1 - 1)
                    break
            if not found:
                memo[u] = 1
                for v in graph[u]:
                    memo[u] += memo[v]
                if time_diff > 0:
                    time_diff += 2
                else:
                    time_diff += 1
            state_tracker[(u + 1) % 2].append(time_diff - memo[u])

    # Propagate once to explore the entire tree
    propagate()

    # Find the minimum time to make one vertex 1 (black)
    min_time = float('inf')
    for u in range(tree_count):
        state_tracker[u % 2].append(1)
        propagate()
        if state_tracker[u % 2][-1] > 0:
            min_time = min(min_time, state_tracker[u % 2][-1] % 2)
        state_tracker[u % 2].pop()

    # Propagate again from the starting point through each vertex
    for start in range(tree_count):
        s_time = 0
        state_tracker[0].append(s_time)
        for u in edges[start]:
            m = {}
            m[0] = 0
            q = [(0, start)]
            while q:
                c, u = q.pop(0)
                pair = (c + 1 if u % 2 != 0 else c - 1)
                m[pair] = max(m[pair] or -1, state_tracker[u % 2][-1] - state_tracker[u % 2][0])
                for v in graph[u]:
                    if graph[u][v] in m:
                        q.append((m[graph[u][v]], v))
                    else:
                        m[graph[u][v]] = max(m[graph[u][v]], m[pair])
            m = {au: av - s_time for u, au in enumerate(state_tracker) for v, av in enumerate(m) if u or v}
            state_tracker[start].append(state_tracker[start][-1] + 1 + s_time)
            for u, m in enumerate(m):
                # Must ensure two single room gates at any start point
                if m[u] == 1 and u != start - 1:
                    state_tracker[start][-1] = -1
                    break
            s_time += 1
        state_tracker[start].pop()

        time_to_blackify = min(time_to_blackify, max(state_tracker[start][-1] <= 0, min_time) - s_time)

    return time_to_blackify
