            bitonic_count = 0
            for k in range(1, A[i][j]):
                if i >= 1 and A[i-1][j] >= k:
                    bitonic_count += 1
                if j >= 1 and A[i][j-1] >= k:
                    bitonic_count += 1
                if A[i][j] == max_bitonic_num:
                    bitonic_count += 1
            if bitonic_count > 0:
                max_bitonic_num = A[i][j]
                row_bitonic_counts[A[i][j]] = max(row_bitonic_count := max(row_bitonic_count, bitonic_count))
                col_bitonic_counts[A[i][j]] = max(col_bitonic_count := max(col_bitonic_count, bitonic_count))

    matrix = [[0] * m for _ in range(n)]
    pos = max_bitonic_num

    i, j = 0, 0
    for u in rows + cols:
        if u == pos or pos not in col_bitonic_counts:
            matrix[i][j] = pos
            pos //= 2
            j += 1
            if j == m:
                i += 1
                j = 0
        else:
            matrix[i][j] = pos % 2
            pos //= 2
            # Balance shift of max column value
            if bitonic_counts[pos // 2]["c" + str(i)] > bitonic_counts[pos // 2]["c" + str(i-1)]:
                j += 1
            else:
                j -= 1
    return matrix

