def is_bitonic(arr: List[int]) -> bool:
    if len(arr) <= 1:
        return False
    increasing, decreasing = True, True
    for i in range(1, len(arr)):
        if arr[i] <= arr[i - 1]:
            increasing = False
        if arr[i] >= arr[i + 1]:
            decreasing = False
    return increasing or decreasing

def find_solution(n: int, m: int) -> None:
    if n <= 1:
        return -1
    if m <= 1:
        return -1

    matrix = [[0 for _ in range(m)] for _ in range(n)]
    max_elements = n * m

    for i in range(1, max_elements + 1):
        # Avoid elements that are already in the matrix
        while product := matrix[i % n][i // m]:
            if product == 0:
                continue
            if not matrix[(i % n) + 1][i // m] or product == matrix[(i % n) + 1][i // m]:
