from collections import defaultdict
from math import ceil, sqrt

def find_closest_tree(node, n, k):
    x = node
    for _ in range(k):
        x = (node * floor(sqrt(1 + 2 * x))) % n
    return x

def find_parents(node, n, k):
    x = node
    for _ in range(k):
        x = (node + ceil(sqrt(1 + 2 * x))) % n
    return x

def solve(n, k):
    distances = defaultdict(list)
    for i, j in pairs:
        dist = abs(find_closest_tree(i, n, k) - find_closest_tree(j, n, k))
        distances[dist].append((i, j))
    tree_with_info = set()
    for distances in distances.values():
        l, r = map(find_parents, sorted(range(n), key=lambda x: distances.find(x)), n, k)
        tree_with_info.add(l)
        tree_with_info.add(r)
    return len(tree_with_info)

