def merge_2_elements(nums):
    h, g = map(int, input().split())
    left_size = len([x for x in nums if x < 2*g])
    right_size = h - g - left_size

    new_nums = []
    for i in range(2, len(nums), 2):
        if nums[i] < 2*g or left_size < 2*(g - 1):
            if len(new_nums) > 0 and new_nums[-1] < nums[i]:
                new_nums.append(new_nums.pop())
            new_nums.append(nums[i])
        else:
            left_half = nums[i : min(i + left_size - 1, len(nums))]
            right_half = nums[min(i + left_size, len(nums)) : min(len(nums), i + right_size)]
            for j in range(left_size):
                if len(new_nums) > 0 and new_nums[-1] < left_half[j]:
                    new_nums.append(new_nums.pop())
                new_nums.append(left_half[j])
            for j in range(right_size):
                if len(new_nums) > 0 and new_nums[-1] < right_half[j]:
                    new_nums.append(new_nums.pop())
                new_nums.append(right_half[j])
            if len(new_nums) > 0 and new_nums[-1] < nums[i]:
                new_nums.append(new_nums.pop())
            new_nums.append(nums[i])

    return new_nums

